func FilterServices(serviceData map[string]interface{}, inputRoot string, ship string) (map[string]interface{}, error) {
	shipPath := shipPath(inputRoot, ship)
	shipYaml, err := loadServiceYaml(shipPath)
	if err != nil {
		return nil, err
	}

	shipServices := make(map[string]interface{})
	err = shipYaml.Decode(shipServices)
	if err != nil {
		return nil, err
	}

	var services []map[string]interface{}
	for k, _ := range shipServices {
		for _, service := range (serviceData["services"]).([]map[string]interface{}) {
			if k == service["name"] {
				services = append(services, service)
				break
			}
		}
	}

	return map[string]interface{}{
		"services": sortServices(services),
	}, nil
}

