class IPAddress {
	constructor(Uint8ArrayAddress, netBlock) {
		this.address = Uint8ArrayAddress;
		this.netBlock = netBlock;
	}

	getAddress() {
		return this.address;
	}

	getNetBlock() {
		return this.netBlock;
	}

	isIPv4() {
		return this instanceof IPv4Address;
	}

	isIPv6() {
		return this instanceof IPv6Address;
	}

	static matchToNetwork(ipvxaddress, networkBlock) {
		const bitsInCommon = networkBlock.prefix;
		const networkAddress = networkBlock.network;
		const ipAddress = ipvxaddress.getAddress();

		if (ipAddress.length !== networkAddress.length) return false;

		for (let i = 0; i < bitsInCommon; i++) {
			const networkByte = Math.floor(i / 8);
			const networkBit = 7 - (i % 8);
			const ipByte = Math.floor(i / 8);
			const ipBit = 7 - (i % 8);
			if (
				((networkAddress[networkByte] >> networkBit) & 1) !==
				((ipAddress[ipByte] >> ipBit) & 1)
			) {
				return false;
			}
		}
		return true;
	}
	matchToNetwork() {
		return IPAddress.matchToNetwork(this, this.netBlock);
	}
	getPrefix() {
		return this.netBlock.getPrefix();
	}

	getNetBlock() {
		return this.netBlock;
	}

	toCIDR() {
		if (!this.netBlock) throw new Error("Can't have prefix without netBlock!");
		return this.toString() + "/" + this.getPrefix();
	}

	toHexString() {
		let hexString = "";
		for (let i = 0; i < this.address.length; i++) {
			hexString += this.address[i].toString(16).padStart(2, "0");
		}
		return hexString;
	}
}

